class SubmitLoanRequestModule_AutoGenerated {
  /*if the current loan request exists,
   *and it has the requested CA history and has the request credit history,
   *the current loan request' credit score should be 100 and,
   *the loan request status should be submitted then give the result the current loan request's credit score
   *the current loan request requested ca history should be it*/
  calculateScore(): number {
    /*Definition Start*/
    let hasCaHistory: boolean = l({
      logic: () => StandardOPs.oclIsUndefined(this.RequestedCAHistory),
      description: "self.RequestedCAHistory.oclIsUndefined()",
    }).build().pass;
    let hasCreditHistory: boolean = l({
      logic: () => StandardOPs.oclIsUndefined(this.RequestedCreditHistory),
      description: "self.RequestedCreditHistory.oclIsUndefined()",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => hasCaHistory === false,
        description: "hasCaHistory=false",
      })
        .and({
          logic: () => hasCreditHistory === false,
          description: "hasCreditHistory=false",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(this, LoanRequest),
          description: "self.oclIsTypeOf(LoanRequest)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => (this.CreditScore = 100),
      description: "self.CreditScore=100",
    })
      .and({
        execute: () => (this.Status = LoanRequestStatus.SUBMITTED),
        description: "self.Status=LoanRequestStatus::SUBMITTED",
      })
      .and({
        execute: () => this.CreditScore,
        description: "result=self.CreditScore",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { SubmitLoanRequestModule_AutoGenerated };

